import{_ as t,a as s,o,a6 as i}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Get Admin Permissions","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-permissions-all","title":"Full Access Token","description":"A token whose role grants full access returns the `all` permission type and a single wildcard.","query":"curl -X GET \\"https://your-domain.com/api/admin/permissions\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n","response":"[\\n  {\\n    \\"id\\": \\"permissions\\",\\n    \\"permissionType\\": \\"all\\",\\n    \\"permissions\\": [\\"*\\"]\\n  }\\n]\\n"},{"id":"admin-permissions-custom","title":"Custom Access Token","description":"A token with a restricted role returns the `custom` permission type and the explicit list of granted ACL keys.","query":"curl -X GET \\"https://your-domain.com/api/admin/permissions\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n","response":"[\\n  {\\n    \\"id\\": \\"permissions\\",\\n    \\"permissionType\\": \\"custom\\",\\n    \\"permissions\\": [\\"catalog\\", \\"catalog.products\\", \\"sales.orders\\"]\\n  }\\n]\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/navigation/permissions.md","filePath":"api/rest-api/admin/navigation/permissions.md","lastUpdated":1787290888000}'),n={name:"api/rest-api/admin/navigation/permissions.md"};function a(r,e,d,c,l,p){return o(),s("div",null,e[0]||(e[0]=[i('<h1 id="get-admin-permissions" tabindex="-1">Get Admin Permissions <a class="header-anchor" href="#get-admin-permissions" aria-label="Permalink to &quot;Get Admin Permissions&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/permissions</code></td><td>GET</td></tr></tbody></table><p>Returns the authenticated token&#39;s effective permissions so you can gate UI up front — show or hide buttons, menus and actions without triggering trial-and-error <code>403</code> responses.</p><p>The response is a one-element array describing the token&#39;s access.</p><h2 id="response-fields" tabindex="-1">Response Fields <a class="header-anchor" href="#response-fields" aria-label="Permalink to &quot;Response Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>String</td><td>Identifier of the payload, always the literal <code>permissions</code>.</td></tr><tr><td><code>permissionType</code></td><td>String</td><td>One of <code>all</code>, <code>custom</code>, or <code>same_as_web</code>.</td></tr><tr><td><code>permissions</code></td><td>Array</td><td>The granted ACL keys, or <code>[&quot;*&quot;]</code> for full access.</td></tr></tbody></table><h2 id="permission-modes" tabindex="-1">Permission Modes <a class="header-anchor" href="#permission-modes" aria-label="Permalink to &quot;Permission Modes&quot;">​</a></h2><ul><li><code>all</code> — full access. <code>permissions</code> is the single-element <code>[&quot;*&quot;]</code>, never an expanded list of keys.</li><li><code>custom</code> — <code>permissions</code> lists the explicitly granted ACL keys, frozen onto the token when it was generated.</li><li><code>same_as_web</code> — the token mirrors the owning admin&#39;s current role, so the returned keys change whenever that role changes.</li></ul><p>In every case the effective <code>permissions</code> are capped by the owning admin&#39;s role — a token can never do more than its owner currently can.</p><h2 id="using-the-result" tabindex="-1">Using the Result <a class="header-anchor" href="#using-the-result" aria-label="Permalink to &quot;Using the Result&quot;">​</a></h2><p>Match a key against the <code>permission</code> field of a <a href="/api/rest-api/admin/navigation/menu.html">menu</a> node, or against the ACL key named on an endpoint&#39;s page, to decide whether to render its UI.</p><p>Two things to handle:</p><ul><li><strong><code>[&quot;*&quot;]</code> is a wildcard, not a key.</strong> A literal <code>permissions.includes(&#39;sales.orders&#39;)</code> returns false for a full-access token. Branch on <code>permissionType === &#39;all&#39;</code> first.</li><li><strong>Keys are exact, not prefixes.</strong> Holding <code>catalog</code> does not imply <code>catalog.products</code> — the example above lists both because both were granted. Check the exact key an endpoint requires.</li></ul><p>Gating on this endpoint is advisory. The API re-checks on every call, so a client that skips the check still gets a <code>403</code> rather than unauthorized access.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>A request without a valid token returns HTTP <code>401</code> with <code>{&quot;message&quot;: &quot;Unauthenticated.&quot;, &quot;error&quot;: &quot;unauthenticated&quot;}</code>. Any valid token can call this endpoint — there is no permission gate on it.</p>',16)]))}const u=t(n,[["render",a]]);export{m as __pageData,u as default};
